programs.haiku:
"""Layer 15, MLP down_proj, component 4254.

What it does: its output direction promotes contrast words ("rather", "instead", "than",
"versus"). Its activation is mostly small, unstructured noise, and it has two readable
events:

- Negative on the connectives of a contrast: "rather" / "instead", the "than" of
  "rather than", the "of" of "instead of", and a ", not" that corrects the clause before it.
- Positive, weakly, on the predicate noun of "is / as / be / not a X" and "matter of X",
  where the component is most often important to the model.

Everything else predicts 0. The values are rough averages of what the component does on
those words, not a fitted model. This program explains only a sliver of the variance: the
bulk of the activation is symmetric noise with no lexical pattern, and the rare large
positive firings are not captured by these few cues.
"""

READS = ()

# Words that can sit before "a/an" in a predicate: "X is a Y", "as a Y", "not a Y".
PREDICATE_BEFORE_ARTICLE = {"is", "are", "was", "were", "be", "as", "not", "become", "becomes"}


def _word(prefix, i):
    """Lowercased word at position i, or "" if it is outside the current document."""
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[prefix.position]:
        return ""
    return prefix.token_strings[i].strip().lower()


def step(carry, prefix, upstream):
    t = prefix.position
    cur, p1, p2 = _word(prefix, t), _word(prefix, t - 1), _word(prefix, t - 2)
    if cur in ("rather", "instead"):
        value = -0.8  # the contrast connective itself
    elif cur == "than" and p1 == "rather":
        value = -1.9  # "rather than"
    elif cur == "of" and p1 == "instead":
        value = -1.2  # "instead of"
    elif cur == "not" and p1 == ",":
        value = -1.1  # ", not Y" correction
    elif p1 in ("a", "an") and p2 in PREDICATE_BEFORE_ARTICLE:
        value = 0.2  # predicate noun: "is a X", "not a X"
    elif p1 == "of" and p2 == "matter":
        value = 1.0  # "a matter of X"
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP hidden unit 4268 (down_proj component 4268): an indentation spike.

In plain terms: this component is near zero almost everywhere, but it rises on the
whitespace that indents a line of code, and it rises most when that line starts a new
block. The biggest values come on the indent right after a line ending in an opening
brace "{" (C-like code, about +1.9 when the new line is indented as deep or deeper), next
after a colon ":" (Python blocks, about +0.8), then after a statement ending in ";" (about
+0.6). Indents that close a block (the line is shallower) or follow an ordinary word
are small. Whitespace in the middle of a line is slightly positive; every other token
predicts 0.

The program only tracks, per document, how each line began: the last non-blank character
of the previous line and that line's indentation width (tab = 4 spaces).
"""

READS = ()


def indent_width(ws):
    return sum(4 if ch == "\t" else 1 for ch in ws)


def line_start_value(end, deeper):
    if end == "{":
        return 1.9 if deeper else 0.1
    if end == ":":
        return 0.8 if deeper else 0.05
    if end == ";":
        return 0.6
    if end == ")":
        return 0.35
    return 0.1


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        carry = {"end": "", "prev_indent": 0, "indent": 0, "text": False, "last": ""}
    value = 0.0
    if s != "" and s.strip() == "" and "\n" not in s:  # a pure indentation token
        if carry["text"]:
            value = 0.07  # whitespace inside a line
        else:
            deeper = indent_width(s) >= carry["prev_indent"]
            value = line_start_value(carry["end"], deeper)
    for k, part in enumerate(s.split("\n")):
        if k > 0:  # a newline closes the current line
            if carry["text"]:
                carry["end"], carry["prev_indent"] = carry["last"], carry["indent"]
            carry["indent"], carry["text"], carry["last"] = 0, False, ""
        for ch in part:
            if not carry["text"] and ch in " \t":
                carry["indent"] += 4 if ch == "\t" else 1
            elif ch not in " \t":
                carry["text"], carry["last"] = True, ch
    return carry, value

"""Layer 15 MLP down-projection, component 4270: a negative "tool use" seam detector.

In plain terms: this component is near zero in ordinary text. It goes negative inside an
agent's tool use, the tool calls it writes and the tool output that comes back, and it is
most negative at the seams of that output:
  * the first token of a tool response (the newline right after <tool_response>) is about
    -11, and the next few tokens about -4; the newlines in the next dozen tokens are about
    -5 and the other words about -1.5, fading after that;
  * once a document has used tools, its newlines outside tool output depend on the last
    tool marker: just after a tool call closes (</tool_call>) about -8.5, inside a call
    about -4.5, after a tool response closes about -2.5;
  * the closer '"}}\n' that ends a tool call is about -7.5, other line closers less;
  * words about running and checking code (test, execute, output, PASS) are mildly negative;
  * a newline that opens a turn header (after <|im_start|>user or <|im_end|>) is about -3
    even before any tool use.

The values are the average activation at each of these places. The program predicts only
those averages, so it explains a small share of the variance (about 0.13 on the training
sample, 0.11 on eval). Most of the rest is a diffuse spread of about +-1 across ordinary
words and code, which no simple rule over the tokens predicts.
"""

READS = ()

TOOL_CALL = "<tool_call>"
TOOL_CALL_END = "</tool_call>"
TOOL_OPEN = "<tool_response>"
TOOL_CLOSE = "</tool_response>"
TURN_MARKS = {"<|im_start|>", "<|im_end|>"}
# The last tool marker seen, which sets how strongly a newline is negative.
PHASE = {TOOL_CALL: "in_call", TOOL_CALL_END: "call_end", TOOL_OPEN: "in_response",
         TOOL_CLOSE: "response_end"}
NEWLINE_BY_PHASE = {"call_end": -8.5, "in_call": -4.5, "response_end": -2.5}
# Line closers of tool calls and code blocks, with their typical values.
CLOSERS = {'"}}\n': -7.5, "]\n": -3.5, "`\n\n": -3.0, "``": -2.0, "}`": -1.6,
           "```": -1.2, "}\n": -1.2, ":\n": -2.0, "[": -1.3}
# Words about running code and reading its output.
RUN_WORDS = {
    "test", "tests", "Test", "Tests", "testing", "Testing", "run", "Run", "running",
    "execute", "execution", "output", "Output", "command", "Command", "PASS", "FAIL",
    "Results", "console", "bash", "EOF",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        # A new document: no tool use yet, no tool response open, no turn begun.
        carry = {"doc": doc, "seen_tools": False, "in_tool": False, "phase": None,
                 "since_open": 99, "since_turn": 99}
    tok = prefix.token_strings[-1]
    newline = "\n" in tok

    if tok in (TOOL_CALL, TOOL_OPEN):
        carry["seen_tools"] = True
    if tok in PHASE:
        carry["phase"] = PHASE[tok]
    if tok == TOOL_OPEN:
        carry["in_tool"], carry["since_open"] = True, 0
    elif tok == TOOL_CLOSE:
        carry["in_tool"] = False
    else:
        carry["since_open"] += 1
    carry["since_turn"] = 0 if tok in TURN_MARKS else carry["since_turn"] + 1

    if tok == TOOL_OPEN:
        value = 0.0
    elif carry["in_tool"]:
        # Inside tool output: strongest at its first token, then fading.
        early = carry["since_open"] <= 12
        if carry["since_open"] == 1:
            value = -11.0
        elif carry["since_open"] <= 5:
            value = -4.0
        elif newline:
            value = -5.0 if early else -1.0
        elif tok in RUN_WORDS:
            value = -1.0
        else:
            value = -1.5 if early else -0.4
    elif carry["seen_tools"] and tok in CLOSERS:
        value = CLOSERS[tok]
    elif carry["seen_tools"] and newline:
        value = NEWLINE_BY_PHASE.get(carry["phase"], -5.0)
    elif newline and carry["since_turn"] in (1, 2):
        value = -3.0
    elif tok in CLOSERS:
        value = CLOSERS[tok]
    elif tok in RUN_WORDS:
        value = -1.0
    else:
        value = 0.0
    return carry, value

"""Subject "it" and the auxiliary or modal that follows it.

Layer 15's MLP writes this component into the residual stream. It is strongly
active on the word "it" when "it" is the subject of a clause, so that a verb
or predicate is coming next, and most strongly on the auxiliary, modal or
copula right after that subject ("it is", "it's", "it was", "it will",
"it can", "it may", "it also"). The program leaves "it" at 0 only after a
preposition ("of it", "with it"); "it" after a verb ("translate it into") is
still scored high, which is a known error. Almost everything else sits near
zero, with a little noise the program does not try to predict.
"""

READS = ()

PREPOSITIONS = {
    "of", "with", "on", "for", "in", "to", "about", "from", "at", "by", "into",
    "onto", "under", "over", "through", "than", "without", "use", "using",
}
AUXILIARIES = {
    # modals, auxiliaries, copulas and the negation or adverbs that sit before a verb
    "is", "was", "be", "been", "has", "have", "had", "will", "would", "can",
    "could", "may", "might", "should", "must", "shall", "are", "were", "does",
    "did", "s", "t", "re", "ll", "d", "not", "also", "just", "really",
    "actually", "still", "already", "probably", "likely", "never", "always",
}
SUBJECT_WORDS = {"this", "that", "they", "he", "she", "we", "you", "i", "which", "there", "who"}

IT_SUBJECT = 8.0  # "it" as a subject
AUX_AFTER_IT = 12.0  # the modal or copula right after a subject "it"
OTHER_AFTER_IT = 2.0  # any other word right after a subject "it"
AUX_AFTER_SUBJECT = 2.0  # an auxiliary after another subject word ("they will")
AUX_ALONE = 0.5  # an auxiliary anywhere else


def word(text):
    """A token as a plain lowercase word: no space, no curly apostrophe, no leading quote."""
    return text.strip().replace("’", "'").lstrip("'").lower()


def step(carry, prefix, upstream):
    cur = word(prefix.token_strings[-1])
    same_document = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = word(prefix.token_strings[-2]) if same_document else None
    if cur == "it":
        value = 0.0 if prev in PREPOSITIONS else IT_SUBJECT
    elif prev == "it":
        value = AUX_AFTER_IT if cur in AUXILIARIES else OTHER_AFTER_IT
    elif prev in SUBJECT_WORDS and cur in AUXILIARIES:
        value = AUX_AFTER_SUBJECT
    elif cur in AUXILIARIES:
        value = AUX_ALONE
    else:
        value = 0.0
    return carry, float(value)
